{
  "mechanisms": [
    {
      "name": "mb_mf_mixture",
      "title": "MB/MF mixture weight",
      "description": "Combines model-based and model-free Q-values for stage-1 decisions using a weighting parameter.",
      "params": [
        {
          "name": "w",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_net = w * q_stage1_mb + (1 - w) * q_stage1_mf",
      "expressible_in_slots": true
    },
    {
      "name": "eligibility_trace",
      "title": "Eligibility trace",
      "description": "Updates the stage-1 model-free Q-value of the chosen action using the stage-2 reward prediction error.",
      "params": [
        {
          "name": "lam",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_stage1_mf[action_1[trial]] += alpha * lam * delta_stage2",
      "expressible_in_slots": true
    },
    {
      "name": "action_matching_bias",
      "title": "Action matching bias",
      "description": "Adds a bias to the stage-2 Q-value of the action that corresponds to the action chosen in stage 1.",
      "params": [
        {
          "name": "theta",
          "bounds": [-5, 5]
        }
      ],
      "evidence": "q2[action_1[trial]] += theta  # action matching bias",
      "expressible_in_slots": true
    },
    {
      "name": "value_decay",
      "title": "Value decay",
      "description": "Decays the model-free Q-values of all unchosen actions at both stages towards zero after each trial.",
      "params": [
        {
          "name": "decay",
          "bounds": [0, 1]
        }
      ],
      "evidence": "unchosen_action_1 = 1 - action_1[trial]\n        q_stage1_mf[unchosen_action_1] *= (1 - decay)\n        \n        unchosen_action_2 = 1 - action_2[trial]\n        q_stage2_mf[state_idx, unchosen_action_2] *= (1 - decay)\n        \n        other_state = 1 - state_idx\n        q_stage2_mf[other_state, 0] *= (1 - decay)\n        q_stage2_mf[other_state, 1] *= (1 - decay)",
      "expressible_in_slots": true
    }
  ]
}
